// xUnit -- Fact vs Theory
public class OrderValidatorTests
{
    [Fact]
    public void ValidOrder_PassesValidation()
    {
        // Arrange
        var order = new Order { Amount = 500, CustomerId = 1 };
        var validator = new OrderValidator();

        // Act
        var result = validator.Validate(order);

        // Assert
        Assert.True(result.IsValid);
    }

    [Theory]
    [InlineData(-100)]
    [InlineData(0)]
    public void NegativeOrZeroAmount_FailsValidation(decimal amount)
    {
        var order = new Order { Amount = amount, CustomerId = 1 };
        var result = new OrderValidator().Validate(order);
        Assert.False(result.IsValid);
    }
}

// Moq -- isolate the unit under test from its dependencies
[Fact]
public async Task ProcessOrder_SavesOrderAndSendsNotification()
{
    var mockRepo = new Mock<IOrderRepository>();
    var mockNotifier = new Mock<INotificationService>();
    mockRepo.Setup(r => r.GetByIdAsync(1)).ReturnsAsync(new Order { Id = 1, Amount = 500 });

    var service = new OrderProcessor(mockRepo.Object, mockNotifier.Object);
    await service.ProcessAsync(1);

    mockRepo.Verify(r => r.SaveAsync(It.IsAny<Order>()), Times.Once);
    mockNotifier.Verify(n => n.SendAsync(It.IsAny<string>()), Times.Once);
}

