// Test data builder -- reduces brittleness vs inline entity construction everywhere
public class OrderBuilder
{
    private Order _order = new Order { Amount = 100, Status = "Pending", CustomerId = 1 };
    public OrderBuilder WithAmount(decimal amount) { _order.Amount = amount; return this; }
    public OrderBuilder WithStatus(string status) { _order.Status = status; return this; }
    public Order Build() => _order;
}
